/* Prism loader. Image resize lives in image-resize-runtime.js so it cannot conflict with Prism or description resize. */
(function () {
    if (typeof document === 'undefined' && typeof importScripts === 'function') {
        importScripts('prism.core.min.js');
        return;
    }

    const inject = (src) => {
        if (typeof document === 'undefined') return;
        if (document.readyState === 'loading') {
            document.write(`<script src="${src}"><\/script>`);
        } else {
            const script = document.createElement('script');
            script.src = src;
            document.head.appendChild(script);
        }
    };

    if (typeof document === 'undefined') return;
    inject('prism.core.min.js');
    inject('image-resize-runtime.js');
})();
